import {chapters} from './gear-lessons.mjs';
import {config,observation} from './config.mjs';
import {readings} from './gear-learning-model.mjs';
import {search} from './search.mjs';
const $=id=>document.getElementById(id),p=new URLSearchParams(location.search),en=p.get('lang')!=='es',l=en?'en':'es',t=(es,eng)=>en?eng:es;
let chapter=Math.min(5,Math.max(0,Number(p.get('chapter'))||0)),v=1,a=0,rig,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,visible=true,last=0,front=false;
document.documentElement.lang=l;
$('language').textContent=en?'ES':'EN';$('language').href='gears.html?lang='+(en?'es':'en')+'&chapter='+chapter;
$('find').textContent=t('Buscar','Search');search($('find'),en);
const labels={eyebrow:['APRENDE TOCANDO / 06 EXPERIMENTOS','LEARN BY DOING / 06 EXPERIMENTS'],heading:['Engranajes: entiende cada vuelta.','Gears: understand every turn.'],intro:['Dientes, fuerza, velocidad y configuración. Manipula el mecanismo, sigue sus marcas y conecta el movimiento con los números.','Teeth, force, speed and configuration. Manipulate the mechanism, follow its witness marks and connect motion to the numbers.'],legend:['Cian: entrada · Ámbar: salida · Arrastra para orbitar','Cyan: input · Amber: output · Drag to orbit'],view:['Vista frontal','Front view'],tooth:['Avanzar un diente','Advance one tooth'],scrubLabel:['Ángulo de entrada · grados','Input angle · degrees'],tryLabel:['PRUÉBALO EN EL BANCO','TRY IT ON THE BENCH'],experiment:['Cambia una cosa. Observa la consecuencia.','Change one thing. Watch the consequence.'],loadTitle:['Aplicación: un torno con tambor de 10 cm de radio','Application: a winch with a 10 cm drum radius'],loadIntro:['Imagina la salida unida al tambor. Compara su fuerza disponible con el peso suspendido; la velocidad de cable corresponde a las rpm seleccionadas, solo si el motor puede sostenerlas.','Imagine the output connected to the drum. Compare its available pull with the hanging weight; cable speed corresponds to the selected rpm only if the motor can sustain them.'],limitsTitle:['Qué representa este banco','What this bench represents'],limits:['Modelo cinemático y balance de potencia en régimen permanente. Dientes esquemáticos, módulo ilustrativo de 2 mm; no calcula tensiones, contacto involuta, aceleraciones ni resistencia de materiales. La animación va a 1/10 de la velocidad indicada para seguir los dientes. El rendimiento es total y supuesto, no una predicción de desgaste.','Steady-state kinematics and power balance. Schematic teeth, illustrative 2 mm module; no tooth stress, involute contact, acceleration or material-strength calculation. Animation runs at 1/10 of indicated speed so you can follow the teeth. Efficiency is an assumed total, not a wear prediction.']};
for(const [id,s]of Object.entries(labels))$(id).textContent=s[+en];
$('next').textContent=t('Continúa: embrague, sincronizador y cambio de primera a segunda →','Continue: clutch, synchronizer and the first-to-second shift →');$('next').href='upshift.html?lang='+l;
chapters.forEach((c,i)=>{const b=document.createElement('button');b.className='tile';b.textContent=`0${i+1} / ${c.title[+en]}`;b.onclick=()=>{chapter=i;v=c.stage===5?1:c.stage===4?0:1;reset()};$('chapters').append(b)});
function update(){const c=chapters[chapter],s=readings(c.stage,v,+$('rpm').value,+$('torque').value,+$('eta').value/100,+$('load').value),fmt=x=>x.toLocaleString(l,{maximumFractionDigits:1});
 $('rpmLabel').textContent=t('Entrada: ','Input: ')+$('rpm').value+' rpm';$('torqueLabel').textContent=t('Par disponible: ','Available torque: ')+$('torque').value+' N·m';$('etaLabel').textContent=t('Rendimiento total: ','Overall efficiency: ')+$('eta').value+' %';$('loadLabel').textContent=t('Peso suspendido: ','Hanging weight: ')+$('load').value+' N';
 const fields=[[t('Salida','Output'),fmt(s.speed)+' rpm'],[t('Par de salida disponible','Available output torque'),fmt(s.out)+' N·m'],[t('Fuerza tangencial total equivalente','Equivalent total tangential force'),fmt(s.force)+' N'],[t('Potencia de entrada','Input power'),fmt(s.power)+' W'],[t('Potencia de salida disponible','Available output power'),fmt(s.delivered)+' W'],[t('Pérdidas en transmisión','Transmission losses'),s.q?fmt(s.loss)+' W':'—']];
 $('readings').replaceChildren(...fields.map(([label,value])=>{const d=document.createElement('div');d.className='reading';const sm=document.createElement('small'),b=document.createElement('b');sm.textContent=label;b.textContent=value;d.append(sm,b);return d}));
 $('formula').textContent=observation(c.stage,v,en)[0];$('result').textContent=s.q?t(`Por cada vuelta de entrada: ${fmt(Math.abs(s.q))} vueltas de salida, ${s.q<0?'sentido contrario':'mismo sentido'}. Par × ${fmt(s.out/+$('torque').value)}.`,`Per input turn: ${fmt(Math.abs(s.q))} output turns, ${s.q<0?'opposite direction':'same direction'}. Torque × ${fmt(s.out/+$('torque').value)}.`):t('Punto muerto: salida desacoplada.','Neutral: output uncoupled.');
 $('loadResult').textContent=fmt(s.lift)+' N '+t('disponibles / ','available / ')+$('load').value+' N '+t('requeridos','required');
 $('loadNote').textContent=(s.canLift?t('Hay margen de par. Velocidad de cable a estas rpm: ','Torque margin available. Cable speed at these rpm: ')+fmt(s.height)+' m/s.':t('Sin margen para elevar de forma sostenida a estas rpm. Aumenta la reducción o el par disponible.','No margin for sustained lifting at these rpm. Increase reduction or available torque.'))+' '+t('F = T/r; v = 2πrn/60. A igualdad de fuerzas no sobra par para acelerar. El giro del banco muestra la relación geométrica, incluso si la carga es excesiva.','F = T/r; v = 2πrn/60. Equal forces leave no torque for acceleration. The bench shows the geometric ratio even when the load is excessive.');
 $('turns').textContent=t('Vueltas: entrada ','Turns: input ')+fmt(a/(Math.PI*2))+' → '+fmt(a/(Math.PI*2)*s.q);$('angle').value=(a*180/Math.PI)%1080;
 $('play').textContent=playing?t('Pausar','Pause'):t('Reproducir','Play');
}
function reset(){a=0;const c=chapters[chapter];$('title').textContent=c.title[+en];$('why').textContent=c.why[+en];$('do').textContent=c.task[+en];$('chapter').textContent=t('EXPERIMENTO ','EXPERIMENT ')+(chapter+1);$('count').textContent='0'+(chapter+1)+' / 06';const [label,opts]=config(c.stage,v,en);$('param').textContent=label;$('setting').replaceChildren(...opts.map((s,i)=>new Option(s,i)));$('setting').value=v;
 $('explain').replaceChildren(...c.cards.map(card=>{const d=document.createElement('article');d.className='tile';const h=document.createElement('h3'),txt=document.createElement('p');h.textContent=card[+en];txt.textContent=card[2+ +en];d.append(h,txt);return d}));
 [...$('chapters').children].forEach((b,i)=>b.setAttribute('aria-current',String(i===chapter)));history.replaceState(null,'','?lang='+l+'&chapter='+chapter);$('language').href='?lang='+(en?'es':'en')+'&chapter='+chapter;rig?.setup(c.stage,v);front=false;update();}
$('setting').onchange=()=>{v=+$('setting').value;reset()};for(const id of ['rpm','torque','eta','load'])$(id).oninput=update;
$('play').onclick=()=>{playing=!playing;update()};$('angle').oninput=()=>{playing=false;a=+$('angle').value*Math.PI/180;update()};$('tooth').onclick=()=>{playing=false;const s=readings(chapters[chapter].stage,v,120,6);a+=Math.PI*2/s.teeth;update()};$('view').onclick=()=>{front=!front;rig?.view(front,chapters[chapter].stage)};
new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;last=0}).observe($('stage'));
try {const {bench}=await import('./model.mjs');rig=bench($('stage'))}catch{ $('stage').textContent=t('El 3D requiere WebGL. Los controles y cálculos siguen disponibles.','3D needs WebGL. Controls and calculations remain available.') }
reset();let refresh=0;function frame(now){const dt=last?Math.min((now-last)/1000,.1):0;last=now;if(visible&&!document.hidden){if(playing){a+=dt*+$('rpm').value*Math.PI/30*.1;if(now-refresh>100){update();refresh=now}}rig?.draw(a)}else last=0;requestAnimationFrame(frame)}requestAnimationFrame(frame);
